"""Export all model-visible document-v2 instructions and interface schemas."""

import argparse
import json
from pathlib import Path

from agents.document import build
from pydantic_ai.models.function import FunctionModel
from pydantic_ai.messages import ModelResponse, TextPart


def export(root, output):
    """Capture the actual schemas generated by PydanticAI.

    Args:
        root: Project root.
        output: Destination Markdown file.
    """
    captured = {}

    def respond(messages, info):
        captured.update(tools=[t.__dict__ for t in info.function_tools],
                        output=[t.__dict__ for t in info.output_tools], instructions=info.instructions)
        return ModelResponse(parts=[TextPart("preview")])

    agent = build(FunctionModel(respond), (root / "prompts/system.txt").read_text())
    try:
        agent.run_sync("Number of measurements: {m}\nExposed sample size: {n}\nUnexposed sample size: {n}\nError criterion: {FWER or FDR}\nFamily level: {numeric value of 0.05/3}\n")
    except Exception:
        if not captured:
            raise
    captured["user_template"] = "Number of measurements: {m}\nExposed sample size: {n}\nUnexposed sample size: {n}\nError criterion: {FWER or FDR}\nFamily level: {numeric value of 0.05/3}\n"
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text("# Exact document-v2 model interfaces\n\n```json\n" + json.dumps(captured, indent=2, default=str) + "\n```\n")


def main():
    """Export the model-input preview without credentials or provider requests."""
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, required=True)
    export(Path.cwd(), parser.parse_args().output)


if __name__ == "__main__":
    main()
